use idenso::reference_cases::{reference_cases, timing::measure, ReferenceDomain};
use std::{fs, path::PathBuf};

fn main() {
    let output = PathBuf::from(std::env::args().nth(1).expect("output directory"));
    fs::create_dir_all(&output).unwrap();
    for case in reference_cases().iter().filter(|case| {
        case.domain == ReferenceDomain::ColorSu3 && case.validation.is_enabled()
    }) {
        let source = case.expression();
        let expected = case.simplify(&source);
        fs::write(output.join(format!("{}.input", case.name)), source.to_string()).unwrap();
        fs::write(output.join(format!("{}.output", case.name)), expected.to_string()).unwrap();
        for sample in 0..3 {
            let (result, diagnostic) = measure(case.name, || case.simplify(&source));
            assert_eq!(result, expected);
            println!("{{\"case\":\"{}\",\"sample\":{},\"diagnostic\":{}}}", case.name, sample, diagnostic);
        }
    }
}
